        language.add("bestiary.confluence.filter.blood_moon.title", "Blood Moon", "血月");
        language.add("bestiary.confluence.filter.boss_enemy.desc", "Bosses are aggressive and resilient enemies that pose a significant challenge to the player.", "Boss 是富有攻击性且强韧的敌怪，向玩家提出了重大挑战。");
