        language.add("bestiary.confluence.filter.corrupt_cave_desert.desc", "The Corruption can spread through the Underground Desert, transforming it into a Corrupt Cave Desert.", "腐化能够通过地下沙漠蔓延，将其转化为腐化洞穴沙漠。");
        language.add("bestiary.confluence.filter.corrupt_cave_desert.title", "Corrupt Cave Desert", "腐化洞穴沙漠");
        language.add("bestiary.confluence.filter.corrupt_desert.desc", "The Corruption can spread through Deserts, transforming them into Corrupt Deserts.", "腐化能够通过沙漠蔓延，将其转化为腐化沙漠。");
        language.add("bestiary.confluence.filter.corrupt_desert.title", "Corrupt Desert", "腐化沙漠");
        language.add("bestiary.confluence.filter.corrupt_ice.desc", "The Corruption can spread through the Underground Snow, transforming it into Corrupt Ice.", "腐化能够通过地下雪原蔓延，将其转化为腐化冰雪。");
