        language.add("bestiary.confluence.filter.crimson_cave_desert.desc", "The Crimson can spread through the Underground Desert, transforming it into a Crimson Cave Desert.", "猩红能够通过地下沙漠蔓延，将其转化为猩红洞穴沙漠。");
        language.add("bestiary.confluence.filter.crimson_cave_desert.title", "Crimson Cave Desert", "猩红洞穴沙漠");
