        language.add("bestiary.confluence.filter.ice.desc", "The Ice is a biome and is the underground variant of the Snow biome.", "地下雪原是一种生物群系，是雪原生物群系的地下版本");
        language.add("bestiary.confluence.filter.ice.title", "Ice", "地下雪原");
        language.add("bestiary.confluence.filter.if_unlocked.desc", "If Unlocked", "已解锁");
