        language.add("bestiary.confluence.filter.old_ones_army.desc", "The Old One's Army is a unique Dungeon Defenders 2 crossover event.", "撒旦军队是个独特的《地牢守护者 2》（Dungeon Defenders 2）联动事件");
        language.add("bestiary.confluence.filter.old_ones_army.title", "Old One's Army", "撒旦军队");
        language.add("bestiary.confluence.filter.party.desc", "A Party is an event that can occur randomly or be manually activated with a Party Center.", "派对是一个事件，可以随机发生，或者用派对中心手动激活。");
        language.add("bestiary.confluence.filter.party.title", "Party", "派对");
        language.add("bestiary.confluence.filter.pirate_invasion.desc", "The Pirate Invasion is a Hardmode invasion event that causes pirate-themed enemies to spawn instead of regular enemies.", "海盗入侵是一个困难模式入侵事件，会使得海盗主题的敌怪代替常规敌怪生成。");
        language.add("bestiary.confluence.filter.pirate_invasion.title", "Pirate Invasion", "海盗入侵");
        language.add("bestiary.confluence.filter.pumpkin_moon.desc", "The Pumpkin Moon is a Hardmode, post-Plantera event with a Halloween theme.", "南瓜月是一个困难模式，世纪之花之后的以万圣节为主题的事件");
        language.add("bestiary.confluence.filter.pumpkin_moon.title", "Pumpkin Moon", "南瓜月");
        language.add("bestiary.confluence.filter.rain.desc", "Rain is an event that affects all surface biomes for its duration.", "雨是一个事件，在其持续时间内会影响所有地表生物群系。");
        language.add("bestiary.confluence.filter.rain.title", "Rain", "下雨");
        language.add("bestiary.confluence.filter.rare_creature.desc", "This creature is very rare.", "这种生物很稀有");
