        language.add("bestiary.confluence.filter.sandstorm.desc", "A Sandstorm is an event exclusive to Deserts that occurs in all Deserts simultaneously.", "沙尘暴是一个专属于沙漠的事件，会同时在所有的沙漠中发生。");
        language.add("bestiary.confluence.filter.sandstorm.title", "Sandstorm", "沙尘暴");
        language.add("bestiary.confluence.filter.sky.desc", "The upper Sky is the layer that forms the top of the world.", "高处的天空是构成世界顶部的地层");
